gslcblas = CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)

class GSLFunction:
    def __init__(self, func):
        self.func = ctypes.CFUNCTYPE(c_double, c_double)(func)
    def __call__(self, x):
        return self.func(x)

class CQuadWorkspace:
    pass

def integrate_function(func, a, b, epsabs, epsrel, workspace_size):
    # Load the GSL C functions into ctypes
    result = c_double()
    abserr = c_double()
    iwork = [0] * 100
    work = ctypes.c_void_p() # Initialize workspace pointer
    error_code = c_int()

    # Create a GSLFunction object and pass it to the C function
    g_func = GSLFunction(func)
    status = gslcblas.gsl_cquad(g_func, a, b, epsabs, epsrel, workspace_size, ctypes.byref(result), ctypes.byref(abserr), iwork, work, ctypes.byref(error_code))

    # Check for error codes and handle them
    if status != 0:
        raise Exception("GSL C function failed with error code %d" % status)

    return {'integral': result.value, 'abs_error': abserr.value, 'num_evals': workspace_size}

