    ws = GSLFilterImpulseWorkspace(K)

    # Allocate and initialize the filter workspace
    filter_ws = gslcblas.gsl_filter_impulse_init(ws.work[:], N)

    # Initialize a noisy sinusoidal signal with occasional outliers
    for i in range(N):
